from .repository import find, listing


def get_document(connection, tenant, owner, document_id):
    """Return the document for (tenant, owner, document_id) or None.

    Any record that does not match all of tenant, owner and an empty
    deleted_at is reported as None, so callers cannot tell a missing,
    cross-tenant, cross-owner or deleted document apart.
    """
    return find(connection, tenant, owner, document_id)


def list_documents(connection, tenant, owner):
    """List live documents for (tenant, owner), ordered by id.

    Results expose only id, title and body; deleted_at never appears.
    """
    return listing(connection, tenant, owner)
